package org.jlinalg.cli;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.file.FileVisitResult;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.SimpleFileVisitor;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.UUID;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Complete declared original-class analyses with native checks and atomic whole-batch admission. */
public final class GseapyWorkflowCli {
    private GseapyWorkflowCli(){ }
    private static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, native-audit.json and every original/process log. SKIP3 skips dependent analysis: export GseapyExecutionSetupCli and prepare the exact permitted runtime separately, or retain the skip. RUN installs nothing. FAIL2 admits no earlier partial case: preserve all originals/provisionals, correct the named input/source/numeric/runtime/timeout/capacity cause, and retry NEW paths. Never refresh old scientific binding hashes.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==1&&args[0].equals("--help")){output.println("java -cp DEVELOPMENT.jar org.jlinalg.cli.GseapyWorkflowCli --request REQUEST.json\nRun explicit original GSEApy1.0.4/1.1.2/1.1.3/1.1.8 class workflows on strict data-only prepared float64 JSON and local gene sets. Native audits check observed equations, identities and full tables. Original draws and GSVA fitting remain upstream. "+ACTION);return 0;}
        Path out=null;int exit=2;var state=new LinkedHashMap<String,Object>();state.put("schema_version",1);state.put("status","RUNNING_UNADMITTED");state.put("result_admitted",false);state.put("atomic_batch",true);state.put("started_at",Instant.now().toString());var warnings=new ArrayList<String>();warnings.add(ACTION);warnings.add("This workflow uses explicit original classes and prepared local gene sets. It does not reconstruct historical remote Enrichr responses, infer missing paper parameters, run a two-tailed hypergeometric test, independently generate permutations or refit a GSVA kernel. Original source statistics are not biological calibration or authenticity certification. Source CSVs remain provisional until the complete Java batch is admitted.");
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request REQUEST.json or --help");Path requestPath=Path.of(args[1]).toAbsolutePath().normalize();require(Files.isRegularFile(requestPath,LinkOption.NOFOLLOW_LINKS)&&requestPath.equals(requestPath.toRealPath()),"Request must be a canonical regular unlinked file");byte[] originalRequest=NextflowFiles.bytes(requestPath,16777216);var requestPin=new NextflowFiles.Pin(originalRequest.length,NextflowFiles.sha(originalRequest));var request=GseapyWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(originalRequest),16777216,4000000)),requestPath.getParent());Path target=canonicalMissing(request.out());require(!Files.exists(target,LinkOption.NOFOLLOW_LINKS)&&Files.isDirectory(target.getParent(),LinkOption.NOFOLLOW_LINKS)&&target.getParent().equals(target.getParent().toRealPath()),"Require NEW output directory under an existing canonical unlinked parent");require(!requestPath.startsWith(target)&&!request.runtime().startsWith(target),"Output overlaps request/runtime metadata");
            for(var input:request.inputs())require(Files.isRegularFile(input.source(),LinkOption.NOFOLLOW_LINKS)&&input.source().equals(input.source().toRealPath())&&!input.source().startsWith(target),"Input must be a canonical regular unlinked file outside output");
            out=Files.createDirectory(target);Files.write(out.resolve("request.original.json"),originalRequest,StandardOpenOption.CREATE_NEW);status(out,state);warnings(out,state,warnings);Path inputs=Files.createDirectory(out.resolve("inputs"));var captured=new LinkedHashMap<String,Path>();var pins=new LinkedHashMap<String,NextflowFiles.Pin>();var preflight=new LinkedHashMap<String,GseapyWorkflowInputs.Prepared>();var captureRecords=new ArrayList<Object>();
            for(int i=0;i<request.inputs().size();i++){
                var input=request.inputs().get(i);var before=NextflowFiles.pin(input.source(),request.inputBytes(),()->{});Path copy=inputs.resolve(input.id()+".json");copy(input.source(),copy,request.inputBytes());require(before.equals(NextflowFiles.pin(copy,request.inputBytes(),()->{}))&&before.equals(NextflowFiles.pin(input.source(),request.inputBytes(),()->{})),"Original input changed during complete capture");captured.put(input.id(),copy);pins.put(input.id(),before);preflight.put(input.id(),GseapyWorkflowInputs.read(copy,request.analyses().get(i),request));captureRecords.add(Map.of("id",input.id(),"original",input.source().toString(),"captured",out.relativize(copy).toString(),"declared_format","prepared-json-float64","declared_source",input.declaredSource(),"bytes",before.bytes(),"sha256",before.sha256()));
            }
            NextflowFiles.writeJson(out.resolve("input-capture.json"),captureRecords);error.println("GSEApy: checking the exact permitted runtime; no installation occurs during RUN.");var runtime=GseapyExecutionRuntime.prepare(request);require(!out.startsWith(runtime.prefix())&&!out.startsWith(runtime.base())&&!runtime.prefix().startsWith(out)&&!runtime.base().startsWith(out),"Analysis output overlaps the bound runtime/base");GseapyExecutionRuntime.sources(out.resolve("source"));var effective=request.worker(captured);NextflowFiles.writeJson(out.resolve("effective-request.json"),effective);error.println("GSEApy: executing every explicit original-class method; all results remain provisional.");var report=GseapyExecutionRuntime.execute(out.resolve("worker"),request,runtime,effective);var workerBefore=manifest(out.resolve("worker"),request);NextflowFiles.writeJson(out.resolve("worker-before-native-audit.json"),workerBefore);var meter=new GseapyExecutionAudit.Meter(request.auditOperations());var audits=new ArrayList<Object>();var cases=list(report.get("cases"));require(cases.size()==request.analyses().size(),"Complete original case family missing");
            for(int i=0;i<cases.size();i++){
                var specification=request.analyses().get(i);var result=object(cases.get(i));String id=text(specification.get("id"));require(text(result.get("id")).equals(id)&&text(result.get("method")).equals(text(specification.get("method")))&&text(result.get("edition")).equals(request.edition()),"Original case identity/order/method/edition changed");error.println("GSEApy: auditing complete original case "+id);audits.add(GseapyExecutionAudit.analyze(specification,out.resolve("worker").resolve(id),preflight.get(id),request,warnings,meter));
            }
            require(workerBefore.equals(manifest(out.resolve("worker"),request)),"Complete worker output changed during native auditing");NextflowFiles.writeJson(out.resolve("native-audit.json"),Map.of("cases",audits,"audit_operations",meter.used,"numeric_states",meter.numeric,"identity_states",meter.identities,"tsv_states",meter.tsv,"nonfinite_states",meter.nonfinite,"independent_permutations",false,"independent_gsva_kernel",false,"python_startup",report.get("python_startup_audit")));error.println("GSEApy: rechecking complete source, input and runtime families before admission.");runtime.verify();GseapyExecutionRuntime.verifySources(out.resolve("source"));for(var input:request.inputs())require(pins.get(input.id()).equals(NextflowFiles.pin(input.source(),request.inputBytes(),()->{}))&&pins.get(input.id()).equals(NextflowFiles.pin(captured.get(input.id()),request.inputBytes(),()->{})),"Original/captured input changed before admission");require(requestPin.equals(NextflowFiles.pin(requestPath,16777216,()->{})),"Original request changed before admission");warnings.add("Read worker/original.stdout, original.stderr and all preserved warnings verbatim. Original warning filters, version-specific source transformations and report conventions remain in force. Process supervision covers owned workers and sampled wall/output limits, not hard OS CPU/memory containment.");state.put("status","PASS_ORIGINAL_GSEAPY_COMPLETE_BATCH");state.put("edition",request.edition());state.put("cases",audits);state.put("paper_reproduced",false);state.put("finished_at",Instant.now().toString());warnings(out,state,warnings);NextflowFiles.writeJson(out.resolve("manifest.json"),manifest(out,request));state.put("manifest_sha256",NextflowFiles.pin(out.resolve("manifest.json"),67108864,()->{}).sha256());state.put("result_admitted",true);status(out,state);output.println("Complete original GSEApy batch admitted: "+out+"\nRead WARNINGS.md and analysis-status.json before using results.");exit=0;
        }catch(GseapyExecutionRuntime.Unavailable failure){exit=3;state.put("status","SKIP3_GSEAPY_DEPENDENCIES_UNAVAILABLE");state.put("error",failure.toString());warnings.add(failure.toString());error.println("GSEAPY SKIP3: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        catch(Exception failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error",failure.toString());warnings.add(failure.toString());error.println("GSEAPY FAIL2: "+failure+"\nREQUIRED ACTION: "+ACTION);failure.printStackTrace(error);}
        catch(OutOfMemoryError failure){state.put("status","FAIL2_JAVA_HEAP_EXHAUSTED");state.put("error",failure.toString());warnings.add("Native memory exhausted; no partial audit or original case is admitted");error.println("GSEAPY FAIL2: Java heap exhausted. "+ACTION);}
        finally{if(exit!=0&&out!=null){state.put("result_admitted",false);state.put("finished_at",Instant.now().toString());try{warnings(out,state,warnings);status(out,state);}catch(IOException failure){error.println("GSEAPY FAIL2: failure receipt could not be finalized: "+failure+". Preserve the whole unadmitted directory.");exit=2;}}if(out!=null)error.println("WARNINGS / REQUIRED ACTIONS: "+out.resolve("WARNINGS.md"));}return exit;
    }
    private static void copy(Path source,Path target,long maximum)throws IOException{try(var input=Files.newInputStream(source,LinkOption.NOFOLLOW_LINKS);var output=Files.newOutputStream(target,StandardOpenOption.CREATE_NEW)){byte[] buffer=new byte[1048576];long size=0;for(int n;(n=input.read(buffer))>=0;){require(n<=maximum-size,"Complete input copy capacity exceeded");output.write(buffer,0,n);size+=n;}}}
    private static Map<String,Object> manifest(Path root,GseapyWorkflowRequest.Request request)throws IOException{
        var files=new TreeMap<String,Object>();var directories=new TreeSet<String>();long[] bytes={0};int[] count={0};Files.walkFileTree(root,new SimpleFileVisitor<>(){
            private void capacity(long size)throws IOException{require(++count[0]<=request.maximumFiles()&&size<=request.outputBytes()-bytes[0],"Complete output capacity exceeded; no partial family admitted");bytes[0]+=size;}
            @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attrs)throws IOException{if(!path.equals(root)){capacity(0);directories.add(root.relativize(path).toString().replace('\\','/'));}return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attrs)throws IOException{String name=root.relativize(path).toString().replace('\\','/');if(name.equals("analysis-status.json")||name.equals("manifest.json"))return FileVisitResult.CONTINUE;require(attrs.isRegularFile()&&!attrs.isSymbolicLink(),"Nonregular original output is outside this workflow");capacity(attrs.size());files.put(name,GseapyExecutionRuntime.pinObject(NextflowFiles.pin(path,request.outputBytes(),()->{})));return FileVisitResult.CONTINUE;}
        });return Map.of("schema_version",1,"directories",directories,"files",files,"captured_bytes",bytes[0],"result_admission","Require analysis-status.json result_admitted=true; originals and data-only observations remain preserved");
    }
    private static Path canonicalMissing(Path path)throws IOException{var suffix=new ArrayDeque<Path>();Path current=path;while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"Missing canonical output ancestor");suffix.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path part:suffix)current=current.resolve(part);return current;}
    private static void status(Path out,Map<String,Object> state)throws IOException{Path temporary=out.resolve(".analysis-status-"+UUID.randomUUID()+".tmp");Files.writeString(temporary,NextflowJson.json(state)+"\n",StandardOpenOption.CREATE_NEW);Files.move(temporary,out.resolve("analysis-status.json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static void warnings(Path out,Map<String,Object> state,List<String> messages)throws IOException{Files.writeString(out.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",messages)+"\n\nRequired action: "+ACTION+"\n");}
}
